const stop = (code: 'ETIMEDOUT' | 'ENOBUFS'): void => {
  failure ??= code;
  signalGroup(child, 'SIGTERM');
  // As execFileSync did: a process outside the group holding a pipe must
  // not keep the stage open past its timeout.
  child.stdout?.destroy();
  child.stderr?.destroy();
};

coveredTest(ctx: CapabilityContext): CoveredTestRun | undefined {
  // Both checkouts: the trusted one decides whether the gate may fold, and
  // the measured one is what `pm run test` there would have run, so a session
  // that edits its own test or pre/post script, or adds a threshold, keeps
  // the two runs (decision 95).
  for (const path of new Set([ctx.configPath, ctx.measurePath])) {
    let scripts: Record<string, string>;
    try {
      scripts = readManifest(path)?.scripts ?? {};
    } catch {
      return undefined;
    }
    if (!PLAIN_VITEST_SCRIPT.test(scripts.test?.trim() ?? '')) return undefined;
    if (scripts.pretest !== undefined || scripts.posttest !== undefined) return undefined;
    if (declaresCoverageThresholds(path)) return undefined;
  }
  const run = instrumentedRun(ctx);
  return isUnavailable(run) ? undefined : run;
},
